<script setup>import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { Check, Play, Clock, BookOpen, Gamepad2, Printer } from 'lucide-vue-next'; import { programs } from '../../data/content'; const route=useRoute(); const course=computed(()=>programs.find(p=>p.slug===route.params.slug)||programs[0]); const lessons=['Meet the skill','Listen and discover','Find it','Trace and practise','Show what you know']</script>
<template><div><section class="detail-hero" :class="course.color"><div class="shell detail-grid"><div><RouterLink to="/programs" class="back-link">← All programs</RouterLink><span class="eyebrow">{{course.subject}} · {{course.age}}</span><h1>{{course.title}}</h1><p>{{course.description}}</p><div class="detail-facts"><span><BookOpen/>{{course.lessons}} lessons</span><span><Clock/>5–10 mins each</span><span><Gamepad2/>Learning games included</span></div><RouterLink class="button" to="/register">Start this program</RouterLink></div><div class="detail-image"><img :src="course.image" :alt="course.title"><div><b>Built for little learners</b><span>Audio guidance · Large controls · Gentle feedback</span></div></div></div></section><section class="section shell course-overview"><div><span class="eyebrow soft">What they’ll learn</span><h2>Clear skills. Playful practice.<br><em>Visible progress.</em></h2><p>This course connects each lesson to reusable activities, skills and recommendations so children always have a meaningful next step.</p><ul class="check-list"><li><Check/> Recognise and name key concepts</li><li><Check/> Practise through games and guided activities</li><li><Check/> Build confidence with independent practice</li><li><Check/> Reinforce learning with related printables</li></ul></div><div class="lesson-plan"><h3>Inside each lesson</h3><ol><li v-for="(lesson,index) in lessons" :key="lesson"><span>{{index+1}}</span><div><b>{{lesson}}</b><small>{{index===2?'Game · skill practice':'Activity · 3–5 mins'}}</small></div><Play v-if="index===2" fill="currentColor"/></li></ol></div></section><section class="course-resource shell"><Printer/><div><h3>Learning continues offline.</h3><p>Every program can recommend printables linked to the exact skill your child is practising.</p></div><RouterLink to="/resources" class="arrow-link">Browse related resources →</RouterLink></section></div></template>
